public class MyContextListener implements ServletContextListener {
    public void contextInitialized(ServletContextEvent sce) {
        // wywolywane RAZ, gdy aplikacja startuje - ZANIM jakikolwiek serwlet obsluzy zadanie
        System.out.println("aplikacja startuje");
    }
    public void contextDestroyed(ServletContextEvent sce) {
        // wywolywane RAZ, gdy aplikacja jest zatrzymywana
        System.out.println("aplikacja sie zatrzymuje");
    }
}

